const creatorThemes={Wemmbu:{accent:'#a970ff',accent2:'#6132a8',art:'⚒'},Parrot:{accent:'#75ed79',accent2:'#168c51',art:'🔭'},Spoke:{accent:'#ff74d5',accent2:'#4eeaff',art:'🗿'},FlameFrags:{accent:'#ff5964',accent2:'#c42336',art:'🗡'}};
